$invoiceId=trim((string)($_GET['id']??''));
?><!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Wholesale Receivables</title>
<style>
:root{--bg:#f2f1ed;--panel:#fff;--ink:#171815;--muted:#6d716b;--line:#deded8;--accent:#d94a2b;--dark:#171b1a;--good:#157347;--warn:#9a6200;--bad:#a62a24;--shadow:0 14px 38px rgba(24,25,21,.08)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif}button,input,select,textarea{font:inherit}.top{min-height:64px;padding:10px 20px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:12px;position:sticky;top:0;z-index:30}.brand{display:flex;align-items:center;gap:11px}.logo{width:38px;height:38px;border-radius:11px;background:var(--dark);display:grid;place-items:center;color:#fff;font-weight:900}.brand small{display:block;color:var(--muted);font-size:9px}.nav{display:flex;gap:7px;flex-wrap:wrap}.btn{min-height:36px;border:1px solid var(--line);border-radius:9px;background:#fff;color:var(--ink);padding:8px 11px;font-size:9px;font-weight:900;text-decoration:none;cursor:pointer}.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}.btn.dark{background:var(--dark);border-color:var(--dark);color:#fff}.btn.good{background:var(--good);border-color:var(--good);color:#fff}.btn.danger{color:var(--bad)}.btn:disabled{opacity:.4;cursor:not-allowed}.shell{max-width:1500px;margin:auto;padding:22px}.hero{display:flex;align-items:end;justify-content:space-between;gap:18px;margin-bottom:15px}.eyebrow{margin:0;color:var(--accent);font-size:9px;font-weight:950;text-transform:uppercase;letter-spacing:.12em}.hero h1{margin:5px 0 6px;font-size:36px;letter-spacing:-.05em}.hero p{margin:0;color:var(--muted);font-size:11px;line-height:1.5;max-width:880px}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin-bottom:14px}.metric{padding:13px;border:1px solid var(--line);border-radius:13px;background:#fff}.metric small{display:block;color:var(--muted);font-size:7px;font-weight:900;text-transform:uppercase}.metric strong{display:block;margin-top:5px;font-size:22px}.layout{display:grid;grid-template-columns:350px minmax(0,1fr);gap:14px}.panel{background:#fff;border:1px solid var(--line);border-radius:15px;box-shadow:0 4px 18px rgba(20,20,18,.03)}.sidebar{padding:12px;position:sticky;top:84px;max-height:calc(100vh - 104px);overflow:auto}.field{width:100%;min-height:39px;border:1px solid var(--line);border-radius:9px;padding:8px 10px;background:#fff}.tabs{display:flex;gap:5px;margin:9px 0}.tab{flex:1}.list{display:grid;gap:7px}.card{border:1px solid var(--line);border-radius:11px;padding:11px;background:#fff;cursor:pointer}.card.active{border-color:var(--accent);box-shadow:0 0 0 2px rgba(217,74,43,.08)}.card strong{font-size:11px}.card p{margin:3px 0 0;color:var(--muted);font-size:9px;line-height:1.4}.tag{display:inline-block;margin-top:7px;padding:4px 7px;border-radius:999px;background:#f1f0ec;font-size:7px;font-weight:900;text-transform:uppercase}.tag.bad{background:#fff0ef;color:var(--bad)}.main{display:grid;gap:12px}.section{padding:16px}.section h2{margin:0 0 5px;font-size:16px}.section>p{margin:0 0 12px;color:var(--muted);font-size:10px;line-height:1.45}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.box{padding:12px;border:1px solid var(--line);border-radius:11px}.box small{display:block;color:var(--muted);font-size:7px;text-transform:uppercase;font-weight:900}.box strong{display:block;margin-top:5px;font-size:18px}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:11px}table{width:100%;border-collapse:collapse;min-width:760px}th,td{padding:9px;border-bottom:1px solid #ecece8;text-align:left;font-size:9px}th{background:#f7f6f2;font-size:7px;text-transform:uppercase;color:#5f635d}tr:last-child td{border-bottom:0}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.wide{grid-column:1/-1}.label{display:block;margin:0 0 4px;color:#575c56;font-size:7px;font-weight:900;text-transform:uppercase}.actions{display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end;margin-top:11px}.note{padding:10px;border-radius:9px;background:#f6f5f2;color:var(--muted);font-size:9px;line-height:1.45}.note.warn{background:#fff5df;color:#73520d}.note.bad{background:#fff0ef;color:#8d2923}.note.good{background:#edf8f2;color:#116641}.empty{padding:24px;border:1px dashed #c9c9c2;border-radius:10px;text-align:center;color:var(--muted);font-size:10px}.status{position:fixed;right:18px;bottom:18px;z-index:70;background:#171b1a;color:#fff;padding:10px 13px;border-radius:10px;font-size:10px;box-shadow:var(--shadow)}.hidden{display:none}.mono{font-variant-numeric:tabular-nums}@media(max-width:1050px){.metrics{grid-template-columns:repeat(3,1fr)}.layout{grid-template-columns:1fr}.sidebar{position:static;max-height:none}.summary{grid-template-columns:1fr 1fr}}@media(max-width:650px){.shell{padding:13px}.hero{align-items:flex-start;flex-direction:column}.hero h1{font-size:30px}.metrics,.summary,.grid{grid-template-columns:1fr}.wide{grid-column:auto}}
</style></head><body>
<header class="top"><div class="brand"><div class="logo">G</div><div><strong>Wholesale A/R</strong><small>Invoices · terms · payments · aging · recognized revenue</small></div></div><nav class="nav"><a class="btn" href="wholesale-purchasing.php">Planner</a><a class="btn" href="wholesale-accounts.php">Accounts</a><a class="btn" href="wholesale-demand.php">Demand</a><a class="btn" href="wholesale-fulfillment.php">Fulfillment</a></nav></header>
<main class="shell"><section class="hero"><div><p class="eyebrow">Wholesale W4</p><h1>Accounts receivable</h1><p>Issue invoices from canonical Wholesale orders, track Net terms and aging, record payments and credits, and publish recognized Wholesale revenue into Sales Intelligence without creating synthetic POS checks or tenders.</p></div><button class="btn" id="refresh">Refresh</button></section><section class="metrics" id="metrics"></section><div class="layout"><aside class="panel sidebar"><input class="field" id="search" placeholder="Search invoice, order, or account…"><div class="tabs"><button class="btn tab dark" id="invoiceTab">Invoices</button><button class="btn tab" id="orderTab">Orders</button></div><div class="list" id="list"><div class="empty">Loading receivables…</div></div></aside><section class="main" id="main"><div class="panel section"><div class="empty">Select an invoice or an uninvoiced order.</div></div></section></div></main><div class="status hidden" id="status"></div>
<script>window.WR={csrf:<?=json_encode(app_csrf_token(),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,id:<?=json_encode($invoiceId)?>,canManage:<?=$canManage?'true':'false'?>};</script>
<script>
(()=>{const cfg=window.WR,by=id=>document.getElementById(id);let invoices=[],orders=[],aging={},detail=null,mode='invoices',active=cfg.id||'';const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));const money=v=>Number(v||0).toLocaleString(undefined,{style:'currency',currency:'USD'});const today=()=>new Date().toISOString().slice(0,10);function toast(t){const e=by('status');e.textContent=t;e.classList.remove('hidden');setTimeout(()=>e.classList.add('hidden'),2400)}async function get(url){const r=await fetch(url,{headers:{Accept:'application/json'},cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Request failed');return d}async function post(body){const r=await fetch('api/wholesale-receivables.php',{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-Token':cfg.csrf},body:JSON.stringify({...body,csrf_token:cfg.csrf})}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Request failed');return d}async function load(){const d=await get('api/wholesale-receivables.php?action=list');invoices=d.invoices||[];orders=d.orders||[];aging=d.aging||{};renderMetrics();renderList();if(active)await openInvoice(active)}function renderMetrics(){const m=[['A/R',aging.receivables],['Overdue',aging.overdue],['Current',aging.current],['90+ days',aging.days90plus],['Customer credits',aging.customerCredits]];by('metrics').innerHTML=m.map(x=>`<div class="metric"><small>${esc(x[0])}</small><strong>${money(x[1])}</strong></div>`).join('')}function setMode(next){mode=next;by('invoiceTab').classList.toggle('dark',mode==='invoices');by('orderTab').classList.toggle('dark',mode==='orders');active='';detail=null;renderList();by('main').innerHTML='<div class="panel section"><div class="empty">Select '+(mode==='invoices'?'an invoice':'an order')+'.</div></div>'}function renderList(){const q=by('search').value.trim().toLowerCase();if(mode==='invoices'){const rows=invoices.filter(r=>!q||[r.number,r.orderNumber,r.businessName,r.status].join(' ').toLowerCase().includes(q));by('list').innerHTML=rows.length?rows.map(r=>`<article class="card ${active===r.id?'active':''}" data-invoice="${esc(r.id)}"><strong>${esc(r.number)} · ${esc(r.businessName)}</strong><p>${esc(r.orderNumber)} · due ${esc(r.dueDate||'not set')}</p><span class="tag ${r.daysOverdue?'bad':''}">${esc(r.status)} · ${money(r.balance)}${r.daysOverdue?' · '+r.daysOverdue+'d overdue':''}</span></article>`).join(''):'<div class="empty">No matching invoices.</div>';document.querySelectorAll('[data-invoice]').forEach(el=>el.onclick=()=>openInvoice(el.dataset.invoice));}else{const rows=orders.filter(r=>!r.invoice_id).filter(r=>!q||[r.order_number,r.business_name,r.status,r.payment_terms].join(' ').toLowerCase().includes(q));by('list').innerHTML=rows.length?rows.map(r=>`<article class="card" data-order="${esc(r.public_id)}"><strong>${esc(r.order_number)} · ${esc(r.business_name)}</strong><p>${esc(r.status)} · ${money(r.total)} · ${esc(r.payment_terms||'Due on receipt')}</p><span class="tag">${r.status==='delivered'?'ready to issue':'draft invoice available'}</span></article>`).join(''):'<div class="empty">No uninvoiced Wholesale orders.</div>';document.querySelectorAll('[data-order]').forEach(el=>el.onclick=()=>openOrder(el.dataset.order));}}async function openInvoice(id){mode='invoices';active=id;by('invoiceTab').classList.add('dark');by('orderTab').classList.remove('dark');history.replaceState({},'',`wholesale-receivables.php?id=${encodeURIComponent(id)}`);renderList();const d=await get('api/wholesale-receivables.php?action=detail&id='+encodeURIComponent(id));detail=d.detail;renderInvoice()}function openOrder(id){mode='orders';active=id;renderList();const o=orders.find(x=>x.public_id===id);if(!o)return;by('main').innerHTML=`<section class="panel section"><p class="eyebrow">${esc(o.business_name)}</p><h2>${esc(o.order_number)} · ${esc(o.status)}</h2><p>Create an immutable invoice draft from the canonical order totals and item snapshots. Revenue is not recognized until the invoice is issued, and issuance is blocked until the order is delivered.</p><div class="summary"><div class="box"><small>Order total</small><strong>${money(o.total)}</strong></div><div class="box"><small>Payment terms</small><strong>${esc(o.payment_terms||'Due on receipt')}</strong></div><div class="box"><small>Status</small><strong>${esc(o.status)}</strong></div><div class="box"><small>Delivered</small><strong>${esc(o.delivered_at||'Not yet')}</strong></div></div>${cfg.canManage?`<div class="grid" style="margin-top:12px"><div><label class="label">Issue date</label><input class="field" id="createIssue" type="date" value="${today()}"></div><div><label class="label">Due date (optional)</label><input class="field" id="createDue" type="date"></div><div><label class="label">Payment terms</label><input class="field" id="createTerms" value="${esc(o.payment_terms||'Due on receipt')}"></div><div class="wide"><label class="label">Customer reference / PO</label><input class="field" id="createRef"></div></div><div class="actions"><button class="btn primary" id="createInvoice">Create invoice draft</button></div>`:''}</section>`;if(cfg.canManage)by('createInvoice').onclick=async()=>{try{const d=await post({action:'invoice.create',orderId:id,issueDate:by('createIssue').value,dueDate:by('createDue').value,paymentTerms:by('createTerms').value,customerReference:by('createRef').value});toast(d.message);await load();await openInvoice(d.detail.invoice.id)}catch(e){toast(e.message)}}}function renderInvoice(){const d=detail,i=d.invoice,canAct=cfg.canManage&&!['void'].includes(i.status);const overdue=i.daysOverdue?`<div class="note bad">This invoice is ${i.daysOverdue} day${i.daysOverdue===1?'':'s'} overdue.</div>`:'';by('main').innerHTML=`<section class="panel section"><p class="eyebrow">${esc(i.businessName)}</p><h2>${esc(i.number)} · ${esc(i.status)}</h2>${overdue}<div class="summary"><div class="box"><small>Invoice total</small><strong>${money(i.total)}</strong></div><div class="box"><small>Balance</small><strong>${money(i.balance)}</strong></div><div class="box"><small>Due date</small><strong>${esc(i.dueDate||'Not set')}</strong></div><div class="box"><small>Terms</small><strong>${esc(i.paymentTerms||'Not set')}</strong></div></div></section>${itemsSection(d.items)}${ledgerSection(d.entries)}${actionSection(i,canAct)}`;bindActions(i)}function itemsSection(rows){return `<section class="panel section"><h2>Invoice snapshot</h2><p>These lines are copied from the canonical Wholesale order and do not change if catalog pricing changes later.</p><div class="table-wrap"><table><thead><tr><th>Line</th><th>Item</th><th>Quantity</th><th>Unit price</th><th>Subtotal</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.line_number}</td><td><strong>${esc(r.item_name_snapshot)}</strong><br><small>${esc(r.sku_snapshot||'')} · ${esc(r.sell_uom_snapshot||'')}</small></td><td>${Number(r.quantity)}</td><td>${money(r.unit_price_snapshot)}</td><td>${money(r.line_subtotal)}</td></tr>`).join('')}</tbody></table></div></section>`}function ledgerSection(rows){return `<section class="panel section"><h2>A/R ledger</h2><p>Append-only financial history. Positive entries increase receivables; negative entries reduce them.</p>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Type</th><th>Amount</th><th>Method</th><th>Reference</th><th>Note</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.effective_date)}</td><td>${esc(r.entry_type)}</td><td class="mono">${money(r.amount_delta)}</td><td>${esc(r.payment_method||'')}</td><td>${esc(r.external_reference||'')}</td><td>${esc(r.note||'')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Draft invoice — no A/R entries yet.</div>'}</section>`}function actionSection(i,canAct){if(!canAct)return'';if(i.status==='draft')return `<section class="panel section"><h2>Issue invoice</h2><p>Issuing recognizes Wholesale revenue. The order must already be delivered.</p><div class="grid"><div><label class="label">Issue date</label><input class="field" id="issueDate" type="date" value="${esc(i.issueDate||today())}"></div><div><label class="label">Due date</label><input class="field" id="dueDate" type="date" value="${esc(i.dueDate||'')}"></div><div><label class="label">Payment terms</label><input class="field" id="terms" value="${esc(i.paymentTerms||'')}"></div></div><div class="actions"><button class="btn danger" id="voidInvoice">Void draft</button><button class="btn primary" id="issueInvoice">Issue invoice</button></div></section>`;return `<section class="panel section"><h2>Receivable activity</h2><p>Payments settle A/R only. Credits reduce recognized revenue and can create a customer credit balance. Refunds pay out that credit balance without reducing revenue a second time.</p><div class="grid"><div><label class="label">Action</label><select class="field" id="entryType"><option value="payment.record">Payment</option><option value="credit.record">Credit</option><option value="refund.record">Refund customer credit</option></select></div><div><label class="label">Amount</label><input class="field" id="amount" type="number" min="0.01" step="0.01"></div><div><label class="label">Effective date</label><input class="field" id="effectiveDate" type="date" value="${today()}"></div><div><label class="label">Method</label><input class="field" id="method" placeholder="ACH, check, card, cash…"></div><div><label class="label">Reference</label><input class="field" id="reference" placeholder="Check # / transaction reference"></div><div><label class="label">Note</label><input class="field" id="note"></div></div><div class="actions"><button class="btn danger" id="voidInvoice">Void eligible invoice</button><button class="btn primary" id="recordEntry">Record activity</button></div><div class="note warn" style="margin-top:10px">To refund a paid invoice, record a credit first. That creates a customer credit balance; then record the refund. This prevents revenue from being reduced twice.</div></section>`}function bindActions(i){if(!cfg.canManage)return;const issue=by('issueInvoice');if(issue)issue.onclick=async()=>{try{const d=await post({action:'invoice.issue',invoiceId:i.id,issueDate:by('issueDate').value,dueDate:by('dueDate').value,paymentTerms:by('terms').value});toast(d.message);detail=d.detail;await load();await openInvoice(i.id)}catch(e){toast(e.message)}};const record=by('recordEntry');if(record)record.onclick=async()=>{try{const d=await post({action:by('entryType').value,invoiceId:i.id,amount:by('amount').value,effectiveDate:by('effectiveDate').value,paymentMethod:by('method').value,reference:by('reference').value,note:by('note').value});toast(d.message);detail=d.detail;await load();await openInvoice(i.id)}catch(e){toast(e.message)}};const v=by('voidInvoice');if(v)v.onclick=async()=>{const reason=prompt('Reason for voiding this invoice:');if(!reason)return;try{const d=await post({action:'invoice.void',invoiceId:i.id,reason});toast(d.message);detail=d.detail;await load();await openInvoice(i.id)}catch(e){toast(e.message)}}}by('invoiceTab').onclick=()=>setMode('invoices');by('orderTab').onclick=()=>setMode('orders');by('search').oninput=renderList;by('refresh').onclick=()=>load().catch(e=>toast(e.message));load().catch(e=>toast(e.message));})();
</script></body></html>
